import React from "react";
import Editor from "./Editor";
import {Box} from '@mui/material';

const Code= ()=>{
    return(
        <Box style={{marginTop:'9vh'}}>
            <Editor heading="HTML" icon="/"/>
            <Editor heading="CSS" icon="#"/>
            <Editor heading="JavaScript" icon="()"/>
        </Box>
    )
}

export default Code;
